def isValidBST(root):
    def helper(node, lower, upper):
        if not node:
            return true
        if not (lower < node.val < upper):
            return false
        return helper(node.left, lower, node.val) and helper(node.right, node.val, upper)
    return helper(root, float('-inf'), float('inf'))

