def longest_increasing_subsequence(nums):
    if not nums:
        return 0
    tails = []  # Stores the smallest tail of all increasing subsequences of a given length
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            # Find the smallest tail >= num using binary search
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num  # Replace the tail with the current number
    return len(tails)

